import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
ASSESSMENT_ID = os.getenv("ASSESSMENT_ID", "assessment-id")
SPECIFICATION_ID = os.getenv("SPECIFICATION_ID", "specification-id")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if os.getenv("API_TOKEN"):
    session.headers["Authorization"] = f"Bearer {os.environ['API_TOKEN']}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()


report = {
    "dashboard_operational_metrics": request("GET", "/dashboard"),
    "integration_guidelines": request("GET", "/integration/guidelines"),
    "supply_chain_health_and_efficiency": request("GET", "/supply-chain-health"),
    "environmental_impact_scores": request("GET", f"/impact-scores/{ASSESSMENT_ID}"),
    "material_analysis_results": request("GET", f"/analysisResults/{SPECIFICATION_ID}"),
    "resource_extraction_rates": request("GET", "/resources/extraction"),
    "new_quality_metric": request(
        "POST",
        "/metrics/record",
        json={
            "metric": os.getenv("QUALITY_METRIC_NAME", "quality_metric"),
            "value": float(os.getenv("QUALITY_METRIC_VALUE", "0")),
            "unit": os.getenv("QUALITY_METRIC_UNIT", ""),
            "recordedAt": os.getenv("QUALITY_METRIC_RECORDED_AT"),
        },
    ),
    "automated_incident_response_configuration": request(
        "POST",
        "/responses/automated",
        json={
            "configuration": os.getenv("INCIDENT_RESPONSE_CONFIGURATION", ""),
        },
    ),
    "updated_operational_assessment": request(
        "PUT",
        f"/impact-assessment/{ASSESSMENT_ID}",
        json={
            "operationalData": {},
        },
    ),
}

print(report)

